create table if not exists public.exercise_catalog (
  id text primary key,
  name text not null,
  category text not null check (category in ('Klatka', 'Plecy', 'Nogi', 'Barki', 'Ramiona', 'Core')),
  equipment text not null,
  level text not null,
  image_ref text not null,
  description text not null,
  steps text[] not null default '{}',
  primary_muscles text[] not null default '{}',
  secondary_muscles text[] not null default '{}',
  updated_at timestamptz not null default now()
);

create index if not exists exercise_catalog_category_name_idx
  on public.exercise_catalog (category, name);

alter table public.exercise_catalog enable row level security;

grant select on table public.exercise_catalog to authenticated;

drop policy if exists "Authenticated users can read exercise catalog" on public.exercise_catalog;
create policy "Authenticated users can read exercise catalog"
  on public.exercise_catalog for select
  to authenticated
  using (true);

insert into public.exercise_catalog (
  id, name, category, equipment, level, image_ref, description, steps, primary_muscles, secondary_muscles
) values
  ('bench-press', 'Wyciskanie sztangi na ławce płaskiej', 'Klatka', 'Sztanga · ławka', 'Średni', 'https://images.unsplash.com/photo-1534367610401-9f5ed68180aa?auto=format&fit=crop&w=320&h=260&q=80', 'Bazowe ćwiczenie rozwijające klatkę piersiową, triceps i przednią część barków.', ARRAY['Połóż się stabilnie, ściągnij łopatki i ustaw stopy mocno na podłodze.', 'Chwyć gryf nieco szerzej niż barki i zdejmij go nad środek klatki.', 'Opuść gryf kontrolowanie do mostka, następnie wypchnij go w górę bez blokowania łokci.']::text[], ARRAY['Klatka piersiowa']::text[], ARRAY['Triceps', 'Przedni akton barków']::text[]),
  ('incline-dumbbell-press', 'Wyciskanie hantli skos', 'Klatka', 'Hantle · ławka skośna', 'Początkujący', 'https://images.unsplash.com/photo-1583454110551-21f2fa2afe61?auto=format&fit=crop&w=320&h=260&q=80', 'Wyciskanie na skosie dodatnim mocniej angażuje górną część klatki piersiowej.', ARRAY['Ustaw ławkę pod kątem około 30 stopni i oprzyj całe plecy.', 'Trzymaj hantle na wysokości klatki, nadgarstki ustaw prosto.', 'Wypchnij hantle nad barki i opuść je powoli do pozycji wyjściowej.']::text[], ARRAY['Górna część klatki piersiowej']::text[], ARRAY['Triceps', 'Przedni akton barków']::text[]),
  ('lat-pulldown', 'Ściąganie drążka', 'Plecy', 'Wyciąg górny', 'Początkujący', 'lat-pulldown.jpg', 'Ćwiczenie na najszersze mięśnie grzbietu z łatwą do kontrolowania progresją.', ARRAY['Usiądź stabilnie i zablokuj uda pod poduszkami.', 'Chwyć drążek szeroko, unieś klatkę i opuść barki.', 'Ściągnij drążek do górnej części klatki, prowadząc łokcie w dół.']::text[], ARRAY['Najszersze grzbietu']::text[], ARRAY['Biceps', 'Tylny akton barków', 'Przedramiona']::text[]),
  ('barbell-row', 'Wiosłowanie sztangą', 'Plecy', 'Sztanga', 'Średni', 'https://images.unsplash.com/photo-1581009146145-b5ef050c2e1e?auto=format&fit=crop&w=320&h=260&q=80', 'Ruch przyciągania budujący grubość pleców oraz siłę chwytu.', ARRAY['Stań na szerokość bioder i pochyl tułów, utrzymując neutralne plecy.', 'Chwyć sztangę nachwytem i napnij brzuch.', 'Przyciągnij gryf do dolnych żeber, zatrzymaj na moment i opuść kontrolowanie.']::text[], ARRAY['Najszersze grzbietu', 'Środek pleców']::text[], ARRAY['Tylny akton barków', 'Czworoboczne', 'Biceps', 'Przedramiona', 'Prostowniki grzbietu']::text[]),
  ('chest-supported-row', 'Wiosłowanie z podparciem klatki', 'Plecy', 'Maszyna lub ławka skośna · hantle', 'Początkujący', 'seated-cable-row.png', 'Wiosłowanie z podpartą klatką ogranicza pracę tułowia i pozwala skupić się na mięśniach pleców.', ARRAY['Oprzyj klatkę o podparcie i ustaw stopy stabilnie.', 'Przyciągnij uchwyty w stronę tułowia, prowadząc łokcie za siebie.', 'Opuść ciężar powoli, nie tracąc kontaktu klatki z podparciem.']::text[], ARRAY['Najszersze grzbietu', 'Środek pleców']::text[], ARRAY['Tylny akton barków', 'Czworoboczne', 'Biceps', 'Przedramiona']::text[]),
  ('pec-deck-fly', 'Rozpiętki na maszynie pec deck', 'Klatka', 'Maszyna pec deck', 'Początkujący', 'flat-dumbbell-press.png', 'Izolowane przywodzenie ramion na maszynie pec deck angażuje klatkę piersiową przy stabilnym tułowiu.', ARRAY['Usiądź z plecami opartymi o oparcie i ustaw uchwyty na wysokości klatki.', 'Złącz ramiona przed sobą, lekko uginając łokcie.', 'Wróć powoli do wygodnego rozciągnięcia klatki bez odrywania pleców od oparcia.']::text[], ARRAY['Klatka piersiowa']::text[], ARRAY['Przedni akton barków']::text[]),
  ('barbell-squat', 'Przysiad ze sztangą', 'Nogi', 'Sztanga · stojaki', 'Średni', 'https://images.unsplash.com/photo-1574680096145-d05b474e2155?auto=format&fit=crop&w=320&h=260&q=80', 'Wielostawowy ruch wzmacniający uda i pośladki. Dobierz zakres do swojej mobilności.', ARRAY['Ustaw gryf na górnej części pleców, napnij brzuch i ustaw stopy stabilnie.', 'Cofnij biodra i zegnij kolana, prowadząc je w kierunku palców stóp.', 'Wstań, odpychając podłogę całą stopą i utrzymując napięty tułów.']::text[], ARRAY['Czworogłowe uda', 'Pośladki']::text[], ARRAY['Dwugłowe uda', 'Prostowniki grzbietu', 'Mięśnie brzucha', 'Przywodziciele uda']::text[]),
  ('romanian-deadlift', 'Martwy ciąg rumuński', 'Nogi', 'Sztanga lub hantle', 'Średni', 'romanian-deadlift.png', 'Ruch zawiasowy rozwijający tylną taśmę: pośladki i mięśnie dwugłowe uda.', ARRAY['Stań prosto ze sztangą blisko ud, kolana lekko ugnij.', 'Cofaj biodra, przesuwając gryf wzdłuż nóg i utrzymując proste plecy.', 'Gdy poczujesz rozciąganie tyłu ud, wypchnij biodra w przód i wróć do stania.']::text[], ARRAY['Dwugłowe uda', 'Pośladki']::text[], ARRAY['Prostowniki grzbietu', 'Mięśnie przedramion']::text[]),
  ('lateral-raise', 'Unoszenie hantli bokiem', 'Barki', 'Hantle', 'Początkujący', 'https://images.unsplash.com/photo-1581009146145-b5ef050c2e1e?auto=format&fit=crop&w=320&h=260&q=80', 'Izolowane ćwiczenie na boczną część barków. Wybierz lekki ciężar i prowadź ruch spokojnie.', ARRAY['Stań prosto z hantlami przy biodrach i lekko ugnij łokcie.', 'Unieś ramiona na boki do wysokości barków, bez wzruszania nimi.', 'Opuść hantle powoli, zachowując napięcie mięśni.']::text[], ARRAY['Boczny akton barków']::text[], ARRAY['Czworoboczne']::text[]),
  ('overhead-press', 'Wyciskanie nad głowę', 'Barki', 'Hantle lub sztanga', 'Średni', 'https://images.unsplash.com/photo-1532029837206-abbe2b7620e3?auto=format&fit=crop&w=320&h=260&q=80', 'Wyciskanie pionowe budujące barki i stabilizację tułowia.', ARRAY['Stań stabilnie, napnij brzuch i ustaw ciężar na wysokości barków.', 'Wyciskaj pionowo nad głowę, nie wyginając nadmiernie pleców.', 'Opuść ciężar do barków pod kontrolą.']::text[], ARRAY['Przedni akton barków', 'Boczny akton barków']::text[], ARRAY['Triceps', 'Mięśnie brzucha']::text[]),
