  ('seated-calf-raise', 'Wspięcia na palce siedząc', 'Nogi', 'Maszyna do łydek siedząc', 'Początkujący', 'calf-raise.png', 'Wspięcia siedząc mocniej obciążają mięsień płaszczkowaty łydki.', ARRAY['Usiądź i oprzyj przednią część stóp na platformie, a poduszki ustaw na udach.', 'Unieś pięty wysoko, nie odbijając się od dołu.', 'Opuść pięty powoli, czując rozciągnięcie łydek.']::text[], ARRAY['Płaszczkowaty']::text[], ARRAY['Brzuchaty łydki']::text[]),
  ('machine-ab-crunch', 'Spięcia brzucha na maszynie', 'Core', 'Maszyna do brzucha', 'Początkujący', 'cable-crunch.png', 'Zgięcie tułowia przeciw oporowi maszyny angażuje mięśnie brzucha.', ARRAY['Ustaw siedzisko i poduszki tak, aby ruch zaczynał się w wygodnej pozycji.', 'Zbliż żebra do miednicy, wykonując kontrolowane spięcie brzucha.', 'Wróć powoli do wyprostu bez rozluźniania całego tułowia.']::text[], ARRAY['Prosty brzucha']::text[], ARRAY['Skośne brzucha']::text[]),
  ('roman-chair-back-extension', 'Prostowanie tułowia na ławce rzymskiej', 'Plecy', 'Ławka rzymska', 'Początkujący', 'romanian-deadlift.png', 'Kontrolowany wyprost bioder wzmacnia prostowniki grzbietu i pośladki.', ARRAY['Ustaw podpórki poniżej bioder i zablokuj stopy.', 'Pochyl tułów, utrzymując neutralne plecy i kontrolując zakres.', 'Wyprostuj biodra do linii ciała, napinając pośladki bez przeprostu.']::text[], ARRAY['Prostowniki grzbietu', 'Pośladkowy wielki']::text[], ARRAY['Dwugłowe uda']::text[]),
  ('assisted-pull-up', 'Podciąganie z asystą na maszynie', 'Plecy', 'Maszyna do podciągania z asystą', 'Początkujący', 'lat-pulldown.jpg', 'Asysta odciąża część masy ciała, pozwalając ćwiczyć pionowe przyciąganie i technikę podciągania.', ARRAY['Ustaw obciążenie asystujące i stabilnie uklęknij lub stań na platformie.', 'Opuść barki i przyciągnij klatkę w stronę drążka.', 'Opuść ciało powoli, prostując ramiona pod kontrolą.']::text[], ARRAY['Najszersze grzbietu']::text[], ARRAY['Biceps', 'Obły większy', 'Tylny akton barków', 'Mięśnie przedramion']::text[]),
  ('assisted-dip', 'Dipy z asystą na maszynie', 'Ramiona', 'Maszyna do dipów z asystą', 'Początkujący', 'triceps-pushdown.png', 'Asysta pomaga kontrolować dipy, które angażują triceps oraz klatkę piersiową.', ARRAY['Ustaw obciążenie asystujące i oprzyj dłonie na uchwytach.', 'Ugnij łokcie, opuszczając ciało w wygodnym zakresie.', 'Odepchnij uchwyty i wróć do stabilnej pozycji.']::text[], ARRAY['Triceps']::text[], ARRAY['Klatka piersiowa', 'Przedni akton barków']::text[]),
  ('rotary-torso', 'Rotacje tułowia na maszynie', 'Core', 'Maszyna rotary torso', 'Początkujący', 'cable-crunch.png', 'Kontrolowana rotacja tułowia przeciw oporowi wzmacnia mięśnie skośne brzucha.', ARRAY['Usiądź stabilnie, oprzyj klatkę o podparcie i ustaw zakres maszyny.', 'Obróć tułów w jedną stronę, utrzymując biodra nieruchomo.', 'Wróć powoli do środka i wykonaj drugą stronę.']::text[], ARRAY['Skośne brzucha']::text[], ARRAY['Prosty brzucha', 'Mięsień poprzeczny brzucha']::text[]),
  ('machine-biceps-curl', 'Uginanie ramion na maszynie na biceps', 'Ramiona', 'Maszyna do uginania ramion', 'Początkujący', 'preacher-curl.png', 'Uginanie łokci na maszynie izoluje biceps przy stabilnym podparciu ramion.', ARRAY['Ustaw siedzisko i oprzyj ramiona o poduszki zgodnie z konstrukcją maszyny.', 'Ugnij łokcie, unosząc uchwyty bez odrywania ramion od podparcia.', 'Opuść ciężar powoli do pozycji początkowej.']::text[], ARRAY['Biceps']::text[], ARRAY['Mięsień ramienny', 'Mięsień ramienno-promieniowy']::text[]),
  ('horizontal-leg-press', 'Wypychanie na suwnicy poziomej', 'Nogi', 'Suwnica pozioma', 'Początkujący', 'leg-press.png', 'Pozioma suwnica pozwala trenować uda i pośladki w stabilnej pozycji siedzącej.', ARRAY['Usiądź z plecami opartymi o oparcie i ustaw stopy na platformie.', 'Opuść platformę, zginając kolana bez odrywania bioder od siedziska.', 'Wypchnij platformę płynnie, nie blokując kolan.']::text[], ARRAY['Czworogłowe uda']::text[], ARRAY['Pośladki', 'Przywodziciele uda']::text[]),
  ('machine-chest-dip', 'Dipy na maszynie na klatkę piersiową', 'Klatka', 'Maszyna do dipów', 'Początkujący', 'flat-dumbbell-press.png', 'Wersja dipów z lekkim pochyleniem tułowia mocniej angażuje klatkę piersiową.', ARRAY['Chwyć uchwyty i ustaw tułów lekko pochylony, stabilizując barki.', 'Ugnij łokcie i opuść ciało w zakresie bez bólu w barkach.', 'Odepchnij uchwyty, wracając do góry bez gwałtownego blokowania łokci.']::text[], ARRAY['Klatka piersiowa']::text[], ARRAY['Triceps', 'Przedni akton barków']::text[]),
  ('incline-barbell-press', 'Wyciskanie sztangi na ławce skośnej', 'Klatka', 'Sztanga · ławka skośna', 'Średni', 'incline-smith-press.png', 'Wyciskanie sztangi pod skosem dodatnim akcentuje górną część klatki piersiowej.', ARRAY['Ustaw ławkę pod niewielkim skosem, ściągnij łopatki i oprzyj stopy.', 'Opuść gryf do górnej części klatki, trzymając nadgarstki nad łokciami.', 'Wypchnij gryf nad barki bez odbijania go od klatki.']::text[], ARRAY['Górna część klatki piersiowej']::text[], ARRAY['Triceps', 'Przedni akton barków']::text[]),
  ('push-up', 'Pompki', 'Klatka', 'Masa ciała', 'Początkujący', 'flat-dumbbell-press.png', 'Ćwiczenie z masą ciała rozwija klatkę, triceps i stabilizację tułowia.', ARRAY['Ustaw dłonie nieco szerzej niż barki i utrzymaj ciało w jednej linii.', 'Opuść klatkę w stronę podłogi, prowadząc łokcie po skosie.', 'Odepchnij podłoże i wróć do podporu, nie zapadając bioder.']::text[], ARRAY['Klatka piersiowa']::text[], ARRAY['Triceps', 'Przedni akton barków', 'Mięśnie brzucha']::text[]),
